window.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("litepickerSingleDate");n&&new Litepicker({element:n,format:"MMM DD, YYYY"});const t=document.getElementById("litepickerDateRange");t&&new Litepicker({element:t,singleMode:!1,format:"MMM DD, YYYY"});const i=document.getElementById("litepickerDateRange2Months");i&&new Litepicker({element:i,singleMode:!1,numberOfMonths:2,numberOfColumns:2,format:"MMM DD, YYYY"});const r=document.getElementById("litepickerRangePlugin");r&&new Litepicker({element:r,startDate:new Date,endDate:new Date,singleMode:!1,numberOfMonths:2,numberOfColumns:2,format:"MMM DD, YYYY",plugins:["ranges"]})});